// TH16 v1.00a  Stage 3 boss nonspell  --  th16_s3_b5
// Source: st03bs.ecl.txt Boss3:340-398 (entry) + Boss3_at:400-470 (dependency).
// Shell: control enemy owns the phase; the real boss (invulnerable, body collision kept)
// runs the source attack loop from (0,128).

const TIME_LIMIT: int = 2164;
const OPENING_BUFFER: int = 120;

const TH16_RICE: int = 480;      // source etSprite type 8 -> TH16_RICE

// ---------------------------------------------------------------------------
// Source Boss3_at: per-bullet EX program.
//   record 0  ANIM (a=1)            -> birth animation omitted; its 4*initial_speed
//                                      retreat displacement is folded into sh_dist below
//   record 1  SAVE (0x800000)       -> only the saved angle is read (STEP c=3); captured
//                                      with at_spawn($self_angle)
//   record 2  OFFSCREEN a=160 b=0
//   record 3  STEP a=60 b=1 c=0 d=0 r=90deg s=2.0 (Lunatic 6.0)
//   record 4  STEP a=120(Lunatic 40) b=1 c=3 d=2 r=9999999(saved angle)
//                                      s=2.0(E/N) 3.0(H) 3.8(L)
// STEP: drawn speed falls linearly to zero over a frames while the logical scalar is
// kept; at the segment boundary the angle is updated (c=0 adds r, c=3 restores the SAVE
// angle) and the logical speed is restored to s.
// ---------------------------------------------------------------------------
xformdef RING_STEP(mid_speed: fx, end_speed: fx, seg2: int) {
    offscreen_keep(160);
    step_speed(0fx, 60 + 65536 * EASE_LINEAR);
    wait(60);
    set_speed(mid_speed);                       // c=0 boundary: speed := record s
    turn(90deg);                                // c=0 boundary: angle += r
    step_speed(0fx, seg2 + 65536 * EASE_LINEAR);
    wait(seg2);
    set_angle(at_spawn($self_angle));           // c=3 boundary: angle := SAVE angle
    set_speed(end_speed);                       // final target speed of record 4
}

// ---------------------------------------------------------------------------
// Source Boss3_at body: 12 volleys of a rotating fixed-direction ring.
//   etAim 3 (fixed ring), etCount N/1, etAngle(90deg, 0), etSpeed(2.5, 1.0)
//   $E=12, D starts at 1.5707964 rad and advances by C (+-1deg) after each volley
//   etDist(24) -> net spawn offset 24 - 4*2.5 = 14px along each bullet angle
// ---------------------------------------------------------------------------
async sub ring_burst(color: int, ways: int, gap: int, mid_speed: fx, end_speed: fx,
                     seg2: int, drift: int) {
    sh_reset(0);
    sh_sprite(0, TH16_RICE, color);             // etSprite(8, 4 / 13)
    sh_ring(0, 1);
    sh_aim(0, 0);                               // etAim mode 3: no player aim
    sh_count(0, ways, 1);
    sh_speed(0, 2.5fx, 0fx);                    // single layer takes speed0
    sh_dist(0, 14fx);                           // etDist 24 - ANIM retreat 4*(2.5)
    sh_xform(0, RING_STEP(mid_speed, end_speed, seg2));
    var base: int = 16384;                      // source base angle 1.5707964 rad
    for k in 0..12 {
        sh_angle(0, base as angle, 0deg);
        base = base + drift;
        sh_fire(0);
        wait(gap);
    }
}

// ---------------------------------------------------------------------------
// moveRand(60, 4, 1.0) with moveLimit(0,128,280,96).
// Recipe: movement.md (speed 1 -> 0 linear, direction sampled once, per-frame clamp).
// Box x[-140,140] y[80,176]; direction inner region x+-70, y 104..152.
// ---------------------------------------------------------------------------
sub arm_next_step() {
    var k: int = self_int(0) + 1;
    set_self_int(0, k);
    var speed: fx = 0fx;
    if k < 60 { speed = (60 - k) as fx / 60; }
    var nx: fx = $self_x + self_fx(0) * speed;
    var ny: fx = $self_y + self_fx(1) * speed;
    if nx < -140fx { nx = -140fx; }
    if nx > 140fx { nx = 140fx; }
    if ny < 80fx { ny = 80fx; }
    if ny > 176fx { ny = 176fx; }
    move_vel_xy(0, nx - $self_x, ny - $self_y, EASE_LINEAR);
}

sub begin_move_angle(a: angle) {
    set_self_fx(0, cos(a));
    set_self_fx(1, sin(a));
    set_self_int(0, 0);
    arm_next_step();
}

sub move_rand() {
    var r: int = rand(65536) - 32768;
    var a: int = r / 3;
    if $self_x < -70fx {
        a = r / 3;
    } else if $self_x > 70fx {
        a = r / 3 + 32768;
        if a > 32768 { a = a - 65536; }
    } else {
        a = r / 4;
        var choose: int = rand(65536) % 3;
        if $player_x > $self_x {
            if choose == 0 { a = a + 32768; }
        } else {
            if choose != 0 { a = a + 32768; }
        }
    }
    if $self_y < 104fx {
        if a < 0 { a = -a; }
    } else if $self_y > 152fx {
        if a < 0 { a = -a; }
        a = -a;
    }
    if a > -16906 && a < -15862 {
        if a < -16384 { a = -16906; } else { a = -15862; }
    } else if a > 15862 && a < 16906 {
        if a < 16384 { a = 15862; } else { a = 16906; }
    }
    begin_move_angle(a as angle);
}

sub card_wait(frames: int) {
    for i in 0..frames {
        wait(1);
        arm_next_step();
    }
}

// ---------------------------------------------------------------------------
// Source Boss3 main loop (period 280 frames):
//   @Boss3_at(0, 4, +1deg) async ; wait 80 ; moveRand ; wait 60
//   @Boss3_at(1,13, -1deg) async ; wait 80 ; moveRand ; wait 60
// ---------------------------------------------------------------------------
async sub boss_attack() {
    set_invuln(65535);
    set_hurtbox(20fx);                          // Boss() setHurtbox(40,40) -> r=20
    set_hitbox(24fx);                           // Boss() setHitbox(48,48)  -> r=24
    set_self_int(0, 60);
    set_self_fx(0, 0fx);
    set_self_fx(1, 0fx);

    var ways: int = 12;                         // !E 12 / !N 20 / !H 26 / !LO 30
    var gap: int = 11;                          // volley spacing 11 (Lunatic 9)
    var mid_speed: fx = 2fx;                    // STEP record 3 target speed
    var end_speed: fx = 2fx;                    // STEP record 4 target speed
    var seg2: int = 120;                        // STEP record 4 duration
    if global(GVAR_RANK) == RANK_NORMAL {
        ways = 20;
    } else if global(GVAR_RANK) == RANK_HARD {
        ways = 26;
        end_speed = 3fx;
    } else if global(GVAR_RANK) == RANK_LUNATIC {
        ways = 30;
        gap = 9;
        mid_speed = 6fx;
        end_speed = 3.8fx;
        seg2 = 40;
    }

    loop {
        spawn ring_burst(4, ways, gap, mid_speed, end_speed, seg2, 182);
        card_wait(80);
        move_rand();
        card_wait(60);
        spawn ring_burst(13, ways, gap, mid_speed, end_speed, seg2, -182);
        card_wait(80);
        move_rand();
        card_wait(60);
    }
}

// ---------------------------------------------------------------------------
// Training shell: control owns the phase, the real boss carries the attack.
// ---------------------------------------------------------------------------
async sub attack_pattern() {
    wait(OPENING_BUFFER);
    _ = spawn_enemy(0fx, 128fx, 13700, 0, 0, 0, boss_attack);
}

async sub control() {
    set_invuln(65535);
    set_enemy_flag(ENEMY_NO_BODY, 1);
    phase_begin(0, attack_pattern, TIME_LIMIT, 0);
    wait_spell();
    kill_all_enemies(KILL_SILENT);   // segment over: the source jumps to BossCard3
    loop { wait(1); }
}

sub main() {
    _ = spawn_enemy(0fx, 0fx, 1000, 0, 0, 0, control);
    loop { wait(600); }
}
